    try:
        r=s.get(U, params={"feed":url}, timeout=20)
    except Exception as e:
        return url,None,None,str(e)
    h=r.text
    dbg=re.search(r'feed-debug: (.*?) -->', h)
    pre=re.search(r'<pre class="tape">(.*?)</pre>', h, re.S)
    body=html.unescape(pre.group(1)) if pre else None
    return url, (dbg.group(1) if dbg else None), body, r.status_code

